local function StopNPCByStopType(p1) --[[ StopNPCByStopType | Line: 40 | Upvalues: Common (copy), Debugging (copy) ]]
	if p1.StopType == "CurrentPosition" then
		local v1 = Common.GetBasePart(p1.NPC)
		local Humanoid = p1.NPC:FindFirstChildOfClass("Humanoid")

		if v1 and Humanoid then
			Humanoid:MoveTo(v1.CFrame.Position)
			v1.CFrame = v1.CFrame
		else
			Debugging.Log(p1.NPC, "StopNPCByStopType: No ActualNPC or NPCHuman found.")
		end
