end

local function NewRequestHandler(p1) --[[ NewRequestHandler | Line: 63 | Upvalues: MessageQueue (copy), WaypointLooper (copy), WaypointsVisualization (copy), StopNPCByStopType (copy), Debugging (copy) ]]
	local Config = p1.Config
	local v1 = MessageQueue.GetNewRequest(Config.NPC)

	if v1 == nil then
		return
	end

	if v1.ProcessingState == "Processing" or v1.ProcessingState == "Processed" then
		return
	end

	MessageQueue.SetActiveRequest(Config.NPC, v1)

	if v1.RequestType == "Stop" then
		if p1.Request == nil then
			return
		end

		p1.Request.ProcessingState = "Processed"
		WaypointLooper.EndContinuity(Config.NPC)
		task.spawn(Config.Hooks.StopAcknowledged, Config.NPC, v1.Target)
		WaypointsVisualization.DeleteVisualization(Config.NPC)

		if p1.Target == nil then
			v1.ProcessingState = "Processed"
			p1.StateMachine:ChangeData("Target", nil)

			return
		end

		StopNPCByStopType(Config)
		v1.ProcessingState = "Processed"
		p1.StateMachine:ChangeData("Target", nil)
	else
		p1.StateMachine:ChangeData("Request", v1)
		p1.StateMachine:ChangeData("Target", v1.Target)

		if not v1.Target then
			Debugging.Log(Config.NPC, "No target set for Idle state, cannot change to Pathing or Tracking.")

			return
		end

		Config:ApplyNow()
		task.spawn(Config.Hooks.StartAcknowledged, Config.NPC, v1.Target)

		if not Config.Tracking.Enabled then
			p1.StateMachine:ChangeState("Pathing")

			return
		end

		if typeof(v1.Target) == "Instance" then
			p1.StateMachine:ChangeState("Tracking")
		else
			p1.StateMachine:ChangeState("Pathing")
		end
	end
end

